function osFinanceCalc(){const n=id=>Number(document.getElementById(id)?.value||0),fmt=x=>Number.isFinite(x)?x.toLocaleString("es-ES",{style:"currency",currency:"EUR"}):"—",put=(id,t)=>{const e=document.getElementById(id);if(e)e.textContent=t},staff=x=>x<=0?0:x<=4?30:x<=8?40:x<=12?50:((Math.floor(x/2)<=8?40:50)+(Math.ceil(x/2)<=8?40:50));const a=Math.floor(n("ev-att")),revenue=a*n("ev-price"),cost=a*(n("ev-mat")+n("ev-extra"))+n("ev-venue")+staff(a),margin=n("ev-margin")/100;put("ev-out","Ingresos: "+fmt(revenue)+" · Costes estimados: "+fmt(cost)+" · Beneficio: "+fmt(revenue-cost)+" · Precio objetivo por persona: "+(a>0&&margin<1?fmt(cost/(1-margin)/a):"—"));const price=n("dc-price")/(1+n("dc-vat")/100),discount=n("dc-discount")/100,cb=Math.floor(n("dc-before")),ca=Math.floor(n("dc-after")),before=cb*(price-n("dc-cost"))-n("dc-fixed")-staff(cb),after=ca*(price*(1-discount)-n("dc-cost"))-n("dc-fixed")-staff(ca);put("dc-out","Beneficio antes: "+fmt(before)+" · Después: "+fmt(after)+" · Diferencia: "+fmt(after-before));const net=n("be-price")/(1+n("be-vat")/100),sessions=Math.max(0,Math.min(100,Math.floor(n("be-sessions")))),capacity=Math.max(1,Math.min(50,Math.floor(n("be-cap")))),fixed=n("be-fixed"),goal=n("be-goal");let zero=null,target=null;for(let seats=0;seats<=sessions*capacity;seats++){let left=seats,wages=0;for(let i=0;i<sessions;i++){let occupied=Math.min(capacity,left);wages+=staff(occupied);left-=occupied;}const profit=seats*(net-n("be-var"))-fixed-wages;if(zero===null&&profit>=0)zero=seats;if(target===null&&profit>=goal)target=seats;}put("be-out","Plazas para cubrir gastos: "+(zero??"No alcanzable")+" · Plazas para el objetivo: "+(target??"No alcanzable")+" · Capacidad: "+sessions*capacity+" plazas");}document.addEventListener("input",e=>{if(e.target?.matches?.("[data-fin-calc]"))osFinanceCalc()});
function osCentralAlerts(){
 if(state.mode!=="live")return "";
 const future=(state.sessions||[]).filter(s=>s.status==="scheduled"&&new Date(s.starts_at)>=new Date());
 const over=future.map(s=>({s,c:capacityFor(s.id)})).filter(x=>x.c&&Number(x.c.live_over_capacity||0)>0);
 const issues=(state.reviews||[]).filter(x=>x.review_status==="pending");
 const today=new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Madrid",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
 const posts=(state.organicPublications||[]).filter(x=>["draft","scheduled"].includes(x.publication_status)&&Boolean(x.planned_date||x.scheduled_at)&&(x.planned_date||day(x.scheduled_at))<=today);
 let rows=over.map(x=>'<div class="os-banner danger"><strong>Sobreaforo · '+fmt(x.s.starts_at)+'</strong> · '+esc(x.c.live_expected)+' / '+esc(x.c.capacity)+' plazas '+btn("Ver taller","session:"+x.s.id,"alt")+'</div>').join("");
 if((state.centralImportIssues||[]).length)rows+='<div class="os-banner danger"><strong>'+state.centralImportIssues.length+' incidencias de importación sin resolver</strong></div>';
if((state.centralInbox||[]).length)rows+='<div class="os-banner"><strong>'+state.centralInbox.length+' entradas externas por revisar</strong></div>';
const latest=new Map();for(const check of(state.automatedHealth||[])){if(!latest.has(check.check_key))latest.set(check.check_key,check)}
if(latest.size)rows+='<div class="os-card"><h3>Supervisión automática · cada hora</h3>'+[...latest.values()].map(c=>'<p><strong>'+esc(c.detail)+'</strong> · '+esc(c.metric)+' · '+esc(c.status)+' · '+fmt(c.checked_at)+'</p>').join("")+'</div>';
if(state.centralAlertError)rows+='<div class="os-banner danger">Error de alertas: '+esc(state.centralAlertError)+'</div>';
if(issues.length)rows+='<div class="os-banner danger"><strong>'+issues.length+' incidencias de importación pendientes</strong> · Revisar antes de cambiar reservas.</div>';
 if(posts.length)rows+='<div class="os-banner"><strong>'+posts.length+' publicaciones pendientes</strong> '+btn("Abrir Marketing","nav:marketing","alt")+'</div>';
 return '<div class="os-card"><h2>Centro de alertas</h2><p class="os-muted">Alertas de reservas y publicaciones. La ausencia de alertas no certifica las integraciones.</p>'+(rows||'<p class="os-muted">Sin alertas detectadas en las fuentes cargadas.</p>')+'</div>';
}
