state.instructorPayments=[];state.instructorPaymentMonth="2026-11";state.instructorPaymentBusy=false;
async function loadInstructorPayments(){
 if(state.mode!=="live"||!admin()){state.instructorPayments=[];return}
 const month=state.instructorPaymentMonth||"2026-11";
 const q=await db.from("os_instructor_monthly_payments").select("*").eq("service_month",month+"-01").order("instructor");
 if(q.error)throw q.error;state.instructorPayments=q.data||[];
}
function instructorPaymentsPage(){
 const money=n=>Number(n||0).toLocaleString("es-ES",{style:"currency",currency:"EUR"});
 if(state.mode!=="live"||!admin())return label("Instructores","Accede como administradora para consultar los pagos reales")+'<div class="os-card">Los pagos y las facturas son privados.</div>';
 const a=state.instructorPayments||[],total=a.reduce((s,x)=>s+Number(x.amount_due_eur||0),0),paid=a.filter(x=>x.payment_status==="paid").reduce((s,x)=>s+Number(x.amount_due_eur||0),0);
 return label("Instructores · Pagos","Facturación mensual agrupada por instructora · tarifas actuales por asistentes",btn("Actualizar","refresh","alt"))+
 '<div class="os-card"><label class="os-field" style="max-width:240px">Mes<input id="ip-month" type="month" value="'+esc(state.instructorPaymentMonth)+'"></label><p class="os-muted">Importes calculados a partir de los turnos registrados. Las facturas se adjuntan cuando las recibas, independientemente de si ya has pagado.</p></div>'+
 '<div class="os-metrics"><div class="os-card"><span class="os-muted">Calculado</span><strong>'+money(total)+'</strong></div><div class="os-card"><span class="os-muted">Marcado pagado</span><strong>'+money(paid)+'</strong></div><div class="os-card"><span class="os-muted">Pendiente de verificar/pagar</span><strong>'+money(total-paid)+'</strong></div><div class="os-card"><span class="os-muted">Facturas sin añadir</span><strong>'+a.filter(x=>!x.invoice_number).length+'</strong></div></div>'+
 '<div class="os-card"><h2>Pagos por instructora</h2><div class="os-tablewrap"><table class="os-table"><thead><tr><th>Instructora</th><th>Talleres</th><th>A pagar</th><th>Pago</th><th>Factura</th><th>Acciones</th></tr></thead><tbody>'+
 a.map(x=>'<tr><td><strong>'+esc(x.instructor)+'</strong></td><td>'+x.workshop_count+'</td><td>'+money(x.amount_due_eur)+'</td><td><span class="os-status">'+(x.payment_status==="paid"?"Pagado":"Sin confirmar")+'</span></td><td>'+ (x.invoice_number?esc(x.invoice_number):'Pendiente')+(x.invoice_check==="invoice_amount_mismatch"?' · Revisar importe':'')+'</td><td><button class="os-btn alt" data-ip="pay" data-id="'+x.instructor_id+'">'+(x.payment_status==="paid"?"Revertir pago":"Marcar pagado")+'</button> <button class="os-btn alt" data-ip="invoice" data-id="'+x.instructor_id+'">Añadir factura</button>'+(x.invoice_number?'<button class="os-btn alt" data-ip="file" data-id="'+x.instructor_id+'">Ver archivo</button>':'')+'</td></tr>').join('')+
 '</tbody></table></div>'+(a.length?'':'<p class="os-muted">No hay turnos registrados en este mes.</p>')+'</div>';
}
document.addEventListener("change",async e=>{if(e.target?.id==="ip-month"){state.instructorPaymentMonth=e.target.value;try{await loadInstructorPayments();render()}catch(err){notify(err.message,true)}}});
document.addEventListener("click",async e=>{
 const el=e.target.closest("[data-ip]");if(!el)return;e.preventDefault();e.stopImmediatePropagation();
 if(state.instructorPaymentBusy)return;const x=(state.instructorPayments||[]).find(y=>y.instructor_id===el.dataset.id);if(!x)return;
 try{
 state.instructorPaymentBusy=true;
 if(el.dataset.ip==="pay"){
 const paid=x.payment_status!=="paid";
 if(!confirm(paid?"¿Confirmas que has realizado el pago mensual a "+x.instructor+" por "+money(x.amount_due_eur)+"?":"¿Quitar la confirmación de pago de "+x.instructor+"?"))return;
 const q=await db.from("os_instructor_monthly_invoices").update({payment_status:paid?"paid":"unverified",paid_at:paid?new Date().toISOString().slice(0,10):null,updated_at:new Date().toISOString()}).eq("instructor_id",x.instructor_id).eq("service_month",x.service_month);if(q.error)throw q.error;
 }else if(el.dataset.ip==="invoice"){
 const number=prompt("Número de factura de "+x.instructor,x.invoice_number||"");if(number===null)return;if(!number.trim())return notify("Introduce el número de factura",true);
 const amount=prompt("Importe total de la factura (€)",x.invoice_total_eur??x.amount_due_eur);if(amount===null)return;
 const num=Number(amount.replace(",", "."));if(!Number.isFinite(num)||num<0)return notify("Importe inválido",true);
 const input=document.createElement("input");input.type="file";input.accept=".pdf,image/png,image/jpeg";
 input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>10485760)throw Error("Máximo 10 MB");const path=x.service_month+"/"+x.instructor_id+"/"+Date.now()+"-"+file.name.replace(/[^a-zA-Z0-9._-]/g,"_");const up=await db.storage.from("os-instructor-invoices").upload(path,file,{upsert:false});if(up.error)throw up.error;const q=await db.from("os_instructor_monthly_invoices").update({invoice_number:number.trim(),invoice_total_eur:num,invoice_storage_path:path,holded_status:"not_linked",updated_at:new Date().toISOString()}).eq("instructor_id",x.instructor_id).eq("service_month",x.service_month);if(q.error)throw q.error;await loadInstructorPayments();render();notify("Factura adjuntada")}catch(err){notify(err.message,true)}};
 input.click();return;
 }else if(el.dataset.ip==="file"){
 const q=await db.from("os_instructor_monthly_invoices").select("invoice_storage_path").eq("instructor_id",x.instructor_id).eq("service_month",x.service_month).single();if(q.error)throw q.error;if(!q.data?.invoice_storage_path)return notify("Sin archivo adjunto",true);
 const u=await db.storage.from("os-instructor-invoices").createSignedUrl(q.data.invoice_storage_path,120);if(u.error)throw u.error;window.open(u.data.signedUrl,"_blank","noopener");return;
 }
 await loadInstructorPayments();render();notify("Pago actualizado");
 }catch(err){notify(err.message||"No se pudo actualizar",true)}finally{state.instructorPaymentBusy=false}
},true);


