function instructorFor(id){return state.facilitators.find(x=>x.session_id===id)?.instructor_name}
function actualFor(id){return state.attendance.find(x=>x.session_id===id)?.actual_attendees}
function showSession(id){const s=state.sessions.find(x=>x.id===id);if(!s)return;const reserved=occ(s.id),extra=pendingDemand(s.id),cap=capacityFor(s.id),actual=actualFor(s.id),bookings=state.reservations.filter(r=>r.session_id===id);
open("detail","Taller · "+fmt(s.starts_at),'<div class="os-card"><h3>'+esc(s.title)+'</h3><p><strong>Estado:</strong> '+esc(s.status)+'</p><p><strong>Registradas en OS:</strong> '+reserved+' / '+s.capacity+'</p>'+(extra?'<p class="os-banner"><strong>ATENCIÓN: '+totalDemand(s.id)+' personas previstas para '+s.capacity+' plazas. Sobreaforo: +'+overage(s)+'.</strong> Hay '+extra+' plazas de Atrápalo confirmadas y pendientes de encajar.</p>':'')+(instructorFor(s.id)?'<p><strong>Instructora:</strong> '+esc(instructorFor(s.id))+'</p>':'')+'<p><strong>Desglose de plazas:</strong> Shopify '+(cap?.shopify_seats??0)+' · Atrápalo '+((cap?.atrapalo_registered_seats??0)+(cap?.outstanding_external_seats??extra))+' · Otros '+(cap?.internal_seats??0)+'</p>'+(Number(cap?.provisional_cowlendar_seats||0)>0?'<p class="os-banner"><strong>Cowlendar: '+cap.provisional_cowlendar_seats+' plazas provisionales</strong> recibidas por webhook, pendientes de conciliar con Shopify. No contabilizadas como nuevo cobro.</p>':'')+'<p><strong>Disponibles seguras:</strong> '+(cap?.live_safe_remaining??Math.max(0,s.capacity-totalDemand(s.id)))+'</p><p><strong>Asistentes reales:</strong> '+(actual===undefined?"Sin registrar":actual)+'</p>'+(actual!==undefined&&actual!==reserved?'<p class="os-banner">Diferencia entre reservas y asistentes: '+(reserved-actual)+'. Se conservan las dos cifras.</p>':"")+'</div><h3>Reservas</h3>'+bookings.map(b=>'<div class="os-list"><div>'+esc(b.booking_name)+'<div class="os-muted">'+esc(b.source)+' · '+b.seats+' plazas · '+esc(b.status)+'</div></div>'+btn("Detalle","reservation:"+b.id,"alt")+'</div>').join("")+(bookings.length?"":'<p>Sin reservas</p>')+(extra?'<h3>Reservas Atrápalo fuera del aforo</h3>'+overflowFor(s.id).map(o=>'<p><strong>'+esc(o.booking_name)+'</strong> · '+o.seats+' plazas · '+esc(o.external_reference)+'</p>').join(''):'')+(s.status!=="completed"&&admin()?'<div class="os-actions">'+btn("Editar taller","edit:"+id,"alt")+(s.status==="scheduled"&&new Date(s.starts_at)<=new Date()?btn("Finalizar taller","inv-close-session:"+id):"")+'</div>':"")+(s.status==="completed"?'<p class="os-muted">Asistencia registrada desde el Excel financiero, independientemente de las reservas originales.</p>':"")+historyFor("workshop_sessions",id))}

load();render();db.auth.getSession().then(({data})=>{if(data.session)authProfile().catch(e=>notify(e.message))});
